uint32_t* table = std::new uint32_t[TABLE_SIZE]();
uint32_t currentHash = sortedParticles[0].hash;
table[currentHash] = 0;

for (size_t i = 1; i < particleCount; i++) {
    if (sortedParticles[i].hash != currentHash) {
        currentHash = sortedParticles[i].hash;
        table[currentHash] = i;
    }
}

return table;

